// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createLink, getLinksList, deleteLinks, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const collectionName = uniqueSuffix("Envelope Shape Collection");
    const linkOneUrl = uniqueSuffix("https://envelope-shape-one.example.com/a");
    const linkTwoUrl = uniqueSuffix("https://envelope-shape-two.example.com/b");

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Envelope Shape Collection"
        },
        "name": "Envelope Shape Link One",
        "tags": [],
        "type": "url",
        "url": "https://envelope-shape-one.example.com/a"
    }`;

    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody, {
        "collection.name": collectionName,
        "url": linkOneUrl
    });

    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Envelope Shape Link One");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe(linkOneUrl);
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(Number(getResponseValue(linksPostResponse, "response.id")), 'id').toBeGreaterThan(0);
    expect(Number(getResponseValue(linksPostResponse, "response.collectionId")), 'collectionId').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const collectionId = getResponseValue(linksPostResponse, "response.collectionId");
    const linkOneId = getResponseValue(linksPostResponse, "response.id");

    // Request Body
    const linksPost1RequestBody: string = `{
        "collection": {
            "id": 201
        },
        "name": "Envelope Shape Link Two",
        "tags": [],
        "type": "url",
        "url": "https://envelope-shape-two.example.com/b"
    }`;

    const linksPost1Response = await createLink(client, URL_localhost, headers, linksPost1RequestBody, {
        "collection.id": collectionId,
        "url": linkTwoUrl
    });

    expect(linksPost1Response.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPost1Response, "response.name"), 'name').toBe("Envelope Shape Link Two");
    expect(getResponseValue(linksPost1Response, "response.url"), 'url').toBe(linkTwoUrl);
    expect(getResponseValue(linksPost1Response, "response.collectionId"), 'collectionId').toBe(collectionId);

    const linkTwoId = getResponseValue(linksPost1Response, "response.id");

    try {
        const linksGetResponse = await getLinksList(client, URL_localhost, headers, {
            "collectionId": [collectionId],
            "sort": ["0"]
        });

        expect(linksGetResponse.statusCode, 'status code').toBe(200);

        // BREAKING CHANGE: the payload under "response" is the {data, meta} envelope, not a bare Link[].
        expect(Array.isArray(getResponseValue(linksGetResponse, "response")), 'response is not a bare array').toBe(false);

        const listedLinks = getResponseValue(linksGetResponse, "response.data");
        expect(Array.isArray(listedLinks), 'response.data is an array').toBe(true);
        expect(listedLinks.length, 'response.data length').toBe(2);
        expect(getResponseValue(linksGetResponse, "response.data.0.id"), 'newest link first').toBe(linkTwoId);
        expect(getResponseValue(linksGetResponse, "response.data.0.name"), 'newest link name').toBe("Envelope Shape Link Two");
        expect(getResponseValue(linksGetResponse, "response.data.0.collectionId"), 'newest link collectionId').toBe(collectionId);
        expect(getResponseValue(linksGetResponse, "response.data.1.id"), 'oldest link second').toBe(linkOneId);
        expect(getResponseValue(linksGetResponse, "response.data.1.name"), 'oldest link name').toBe("Envelope Shape Link One");
        expect(getResponseValue(linksGetResponse, "response.data.2"), 'no third link').toBeNull();
        expect(getResponseValue(linksGetResponse, "response.meta.total"), 'meta.total').toBe(listedLinks.length);
        expect(getResponseValue(linksGetResponse, "response.error"), 'no error field').toBeNull();
    } finally {
        // Request Body
        const linksDeleteRequestBody: string = `{
            "linkIds": [
                ${linkOneId},
                ${linkTwoId}
            ]
        }`;

        const linksDeleteResponse = await deleteLinks(client, URL_localhost, headers, linksDeleteRequestBody);

        expect(linksDeleteResponse.statusCode, 'status code').toBe(200);

        expect(getResponseValue(linksDeleteResponse, "response.count"), 'deleted link count').toBe(2);

        const collectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, collectionId);

        expect(collectionsDeleteResponse.statusCode, 'status code').toBe(200);

        expect(getResponseValue(collectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(collectionId);
        expect(getResponseValue(collectionsDeleteResponse, "response.name"), 'deleted collection name').toBe(collectionName);
    }
});
